inbound.set-body:
@{
            var body = context.Request.Body.As(preserveContent: true) ?? new JObject();
            body.Remove("stream");
            body.Remove("model");
            body.Remove("agent");
            body["agent_reference"] = new JObject(
                new JProperty("name", (string)context.Variables["agent-name"]),
                new JProperty("type", "agent_reference"));
            return body.ToString(Newtonsoft.Json.Formatting.None);
        }

trace.message:
@{
                var record = new JObject(
                    new JProperty("event", "ai_usage_error"),
                    new JProperty("schema_version", 1),
                    new JProperty("apim_request_id", context.RequestId.ToString()),
                    new JProperty("event_time", DateTime.UtcNow.ToString("o")),
                    new JProperty("user_oid", context.Variables.GetValueOrDefault("user-oid", "")),
                    new JProperty("user_upn", context.Variables.GetValueOrDefault("user-upn", "")),
                    new JProperty("agent_name", context.Variables.GetValueOrDefault("agent-name", "")),
                    new JProperty("status_code", context.Response == null ? 0 : context.Response.StatusCode),
                    new JProperty("error_source", context.LastError == null ? "" : context.LastError.Source),
                    new JProperty("error_reason", context.LastError == null ? "" : context.LastError.Reason));
                return record.ToString(Newtonsoft.Json.Formatting.None);
            }
